LAYER
  NAME "c_rezago_educativo_porcentaje_analfabetismo"
  STATUS ON
  TYPE POLYGON
  CONNECTIONTYPE POSTGIS
  CONNECTION "host=mxsig-db port=5432 dbname=mdm6data user=postgres password=P0stgr3s"
  DATA "the_geom FROM (SELECT gid, the_geom FROM rezago_educativo_estimacion_inea2025.tematico_indice_alfa) AS t1 USING UNIQUE gid USING SRID=900913"
  METADATA
    "wms_title" "Mapa tematico de la estimación del rezago educativo INEA2025 (porcentaje_analfabetismo)"
    "wms_enable_request" "*"
  END
  CLASS
    STYLE
      NAME "bajo"
      COLOR 255 255 0
      EXPRESSION ([porcentaje_analfabetismo] <=7.5375)
    END
  END
  CLASS
    STYLE
      NAME "medio"
      COLOR 0 128 0
      EXPRESSION ([porcentaje_analfabetismo] >7.5375 and [porcentaje_analfabetismo] <=10.995000000000001)
    END
  END
  CLASS
    STYLE
      NAME "alto"
      COLOR 240 120 15
      EXPRESSION ([porcentaje_analfabetismo] >10.995000000000001 and [porcentaje_analfabetismo] <=15.14)
    END
  END
  CLASS
    STYLE
      NAME "muy_alto"
      COLOR 255 0 0
      EXPRESSION ([porcentaje_analfabetismo] >15.14)
    END
  END
END

